fn flip_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| {
         if c.is_ascii_lowercase() {
             c.to_ascii_uppercase()
         } else if c.is_ascii_uppercase() {
             c.to_ascii_lowercase()
         } else {
             c
         }
     })
     .collect()
}

#[cfg(test)]
mod tests {
    use super::flip_case;

    #[test]
    fn test_empty() {
        let input: Vec<char> = vec![];
        let output = flip_case(input.clone());
        assert_eq!(output, input);
    }

    #[test]
    fn test_ascii_letters() {
        let input: Vec<char> = "aBcZ".chars().collect();
        let output: Vec<char> = "AbCz".chars().collect();
        assert_eq!(flip_case(input), output);
    }

    #[test]
    fn test_non_ascii() {
        let input: Vec<char> = vec!['1', '!', 'ß', 'ç'];
        // 'ß' and 'ç' are non-ASCII, so they stay the same
        let expected = input.clone();
        assert_eq!(flip_case(input), expected);
    }

    #[test]
    fn test_mixed() {
        let input: Vec<char> = "Hello, 世界!".chars().collect();
        let output: Vec<char> = "hELLO, 世界!".chars().collect();
        assert_eq!(flip_case(input), output);
    }
}